NODE_ENV=development
DATABASE_URL=sqlite:///database.db
```

**Loading Mechanism:**
- Uses `dotenv` package to load environment variables from `.env` file
- `require('dotenv').config();` is called at the top of `app.js`
- Variables are accessed via `process.env.VAR_NAME` throughout the application

## Security Concerns with Current Approach

1. **Local Development Only**: This pattern is appropriate only for development environments
2. **No Secrets Rotation**: Hardcoded values don't support dynamic rotation
3. **Version Control Risk**: `.env` files can be accidentally committed to repositories
4. **Limited Access Control**: No fine-grained access controls for different services
5. **No Audit Trail**: No logging of who accessed or modified secrets

## Improved Secrets Management Recommendations

### 1. Environment-Based Configuration Strategy

```javascript
// config.js - Centralized configuration management
require('dotenv').config();

class Config {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.isProduction = this.env === 'production';
    this.isDevelopment = this.env === 'development';
    this.isTest = this.env === 'test';
  }

  getDatabaseUrl() {
    if (this.isDevelopment) {
      return process.env.DATABASE_URL || 'sqlite:///dev.db';
    }

    // In production, get from environment variables set by secrets manager
    return process.env.DATABASE_URL;
  }

  getPort() {
    return process.env.PORT || 3000;
  }

  getJwtSecret() {
    if (this.isDevelopment) {
      // Only for development - never use hardcoded secrets in production
      return process.env.JWT_SECRET || 'dev-secret-key-change-in-production';
    }

    // In production, this must come from secrets manager
    return process.env.JWT_SECRET;
  }
}

module.exports = new Config();
```

### 2. Production-Grade Secrets Management

For production environments, implement one of these patterns:

**AWS Secrets Manager Integration:**
```javascript
// aws-secrets.js
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecret(secretName) {
  try {
    const data = await secretsManager.getSecretValue({ SecretId: secretName }).promise();
    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secret:', error);
    throw error;
  }
}

// Initialize secrets on startup
async function loadProductionSecrets() {
  if (process.env.NODE_ENV === 'production') {
    const secrets = await getSecret('my-app/production');
    // Override process.env with secrets from AWS
    process.env.DATABASE_URL = secrets.DATABASE_URL;
    process.env.JWT_SECRET = secrets.JWT_SECRET;
    process.env.SES_KEY = secrets.SES_KEY;
  }
}

module.exports = { loadProductionSecrets };
```

**HashiCorp Vault Integration:**
```javascript
// vault-secrets.js
const axios = require('axios');

class VaultClient {
  constructor() {
    this.vaultUrl = process.env.VAULT_ADDR;
    this.token = process.env.VAULT_TOKEN;
    this.cache = new Map();
  }

  async getSecret(path) {
    const cacheKey = `secret/${path}`;

    // Check cache first
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    try {
      const response = await axios.get(
        `${this.vaultUrl}/v1/secret/data/${path}`,
        {
          headers: { 'X-Vault-Token': this.token }
        }
      );

      const secretData = response.data.data.data;

      // Cache for 5 minutes
      this.cache.set(cacheKey, secretData);
      setTimeout(() => this.cache.delete(cacheKey), 300000);

      return secretData;
    } catch (error) {
      console.error('Vault access failed:', error.message);
      throw error;
    }
  }
