  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiting to all requests
app.use(limiter);

// Enable CORS with restrictive policies
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || 'https://yourdomain.com',
  credentials: true
}));

// Parse JSON bodies
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

// Sanitize user input (basic example)
app.use((req, res, next) => {
  // Remove any potential malicious properties from query
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      // Remove keys that start with $ or contain dots (MongoDB injection prevention)
      if (key.startsWith('$') || key.includes('.') || key.includes('\') || key.includes('/')) {
        delete req.query[key];
      }
    });
  }
  next();
});

