### 1. Missing Security Headers
The application doesn't implement basic security headers that protect against common attacks.

**Recommendation:**
Add security headers using the `helmet` middleware:

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Add security headers
app.use(helmet());

// Enable additional protections
app.use(helmet.permittedCrossDomainPolicies()); // Disable Adobe Flash/PDF
app.use(helmet.referrerPolicy({ policy: 'same-origin' })); // Control referrer information

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

### 2. No Input Validation/Sanitization
The current routes don't accept parameters, but any future endpoints could be vulnerable to injection attacks.

**Recommendation:**
Implement input validation for any parameterized routes:

```javascript
const express = require('express');
const helmet = require('helmet');
const sanitizer = require('sanitizer');
const app = express();

app.use(helmet());
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Example of a route with input validation
app.get('/users/:id', (req, res) => {
  // Validate input
  const userId = parseInt(req.params.id);
  if (isNaN(userId) || userId <= 0) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Sanitize input
  const cleanId = sanitizer.escape(userId.toString());

  // In a real app, you would query the database with the validated ID
  res.json({ id: cleanId, name: 'User', email: 'user@example.com' });
});
```

