require('dotenv').config();
const express = require('express');
const app = express();

const securityMiddleware = require('./middleware/security');

// Apply security middleware
app.use(securityMiddleware);

// Input validation middleware
const validateUserId = (req, res, next) => {
  const userId = req.params.id;
  if (!userId || !/^[1-9][0-9]*$/.test(userId)) {
    return res.status(400).json({
      error: 'Invalid user ID format'
    });
  }
  next();
};

// Rate limiting (basic implementation)
const rateLimit = new Map();
const RATE_LIMIT_WINDOW = 60 * 1000; // 1 minute
const MAX_REQUESTS = 100;

const rateLimitMiddleware = (req, res, next) => {
  const ip = req.ip;
  const now = Date.now();

  if (!rateLimit.has(ip)) {
    rateLimit.set(ip, []);
  }

  // Remove timestamps outside the window
  const timestamps = rateLimit.get(ip).filter(timestamp => timestamp > now - RATE_LIMIT_WINDOW);
  rateLimit.set(ip, timestamps);

  if (timestamps.length >= MAX_REQUESTS) {
    return res.status(429).json({
      error: 'Rate limit exceeded. Please try again later.'
    });
  }

  // Add current request timestamp
  rateLimit.get(ip).push(now);
  next();
};

app.use(rateLimitMiddleware);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Secure user endpoint with validation
app.get('/users/:id', validateUserId, (req, res) => {
  const users = {
    '1': { id: 1, name: 'Alice', email: 'alice@example.com' },
    '2': { id: 2, name: 'Bob', email: 'bob@example.com' }
  };

  const user = users[req.params.id];
  if (!user) {
    return res.status(404).json({
      error: 'User not found'
    });
  }

  // Remove sensitive data before sending
  const { email, ...safeUser } = user;
  res.json(safeUser);
});

// Updated users endpoint with pagination and rate limiting
app.get('/users', (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const limit = parseInt(req.query.limit) || 10;

  // Input validation
  if (page < 1 || limit < 1 || limit > 100) {
    return res.status(400).json({
      error: 'Invalid pagination parameters'
    });
  }

  const users = [
    { id: 1, name: 'Alice', role: 'user' },
    { id: 2, name: 'Bob', role: 'user' }
  ];

  // Simulate pagination
  const startIndex = (page - 1) * limit;
  const paginatedUsers = users.slice(startIndex, startIndex + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      page,
      limit,
      total: users.length,
      pages: Math.ceil(users.length / limit)
    }
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

