#!/usr/bin/env node

/**
 * Script to check for missing or insecure secrets before startup
 * Run with: node scripts/check-secrets.js
 */

class SecretChecker {
  constructor() {
    this.issues = [];
    this.warnings = [];
  }

  checkDevDefaults() {
    const devDefaults = [
      { name: 'JWT_SECRET', value: process.env.JWT_SECRET },
      { name: 'DB_PASSWORD', value: process.env.DB_PASSWORD },
      { name: 'STRIPE_SECRET_KEY', value: process.env.STRIPE_SECRET_KEY }
    ];

    devDefaults.forEach(secret => {
      if (secret.value && secret.value.includes('default')) {
        this.issues.push(`Insecure default value detected for ${secret.name}`);
      }

      if (!secret.value) {
        this.issues.push(`${secret.name} is not configured`);
      }
    });
  }

  checkLength() {
    const minPasswordLength = 8;
    const minJwtLength = 32;

    if (process.env.DB_PASSWORD && process.env.DB_PASSWORD.length < minPasswordLength) {
      this.issues.push(`DB_PASSWORD is too short (min ${minPasswordLength} characters)`);
    }

    if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < minJwtLength) {
      this.issues.push(`JWT_SECRET is too short (min ${minJwtLength} characters for security)`);
    }
  }

  checkProductionSettings() {
    if (process.env.NODE_ENV === 'production') {
      // In production, localhost origins are suspicious
      if (process.env.ALLOWED_ORIGINS && process.env.ALLOWED_ORIGINS.includes('localhost')) {
        this.warnings.push('ALLOWED_ORIGINS includes localhost in production environment');
      }

      // Check for test API keys
      const stripeKey = process.env.STRIPE_SECRET_KEY || '';
      if (stripeKey.includes('_test_') && !stripeKey.includes('sk_test_')) {
        this.issues.push('Invalid Stripe test key format');
      }
    }
  }

  checkEnvFile() {
    try {
      const fs = require('fs');
      const path = require('path');

      const envPath = path.resolve(process.cwd(), '.env');
      if (!fs.existsSync(envPath)) {
        this.warnings.push('.env file not found - ensure secrets are provided through environment');
      } else {
        // Check if .env file is in git (should be in .gitignore)
        const gitIgnorePath = path.resolve(process.cwd(), '.gitignore');
        if (fs.existsSync(gitIgnorePath)) {
          const gitIgnore = fs.readFileSync(gitIgnorePath, 'utf8');
          if (!gitIgnore.includes('.env')) {
            this.warnings.push('.env file is not in .gitignore - this could lead to secret leakage!');
          }
        }
      }
    } catch (err) {
      this.warnings.push('Could not check .env file status: ' + err.message);
    }
  }

  runChecks() {
    console.log('Running security checks for environment configuration...\n');

    this.checkDevDefaults();
    this.checkLength();
    this.checkProductionSettings();
    this.checkEnvFile();

    if (this.issues.length > 0) {
      console.error('❌ SECURITY ISSUES FOUND:');
      this.issues.forEach(issue => console.error(`  - ${issue}`));
      console.log('\nFix these issues before deploying to production!');
      return false;
    }

    if (this.warnings.length > 0) {
      console.warn('⚠️  WARNINGS:');
      this.warnings.forEach(warning => console.warn(`  - ${warning}`));
      console.log('\nConsider addressing these warnings for improved security.');
    }

    if (this.issues.length === 0 && this.warnings.length === 0) {
      console.log('✅ All security checks passed!');
    }

    return this.issues.length === 0;
  }
}

// Run the checks
const checker = new SecretChecker();
const success = checker.runChecks();

process.exit(success ? 0 : 1);

